// ---------------------------------------------------------------------------
// Business-claims traceability registry (superadmin only, MFA step-up gated).
// ---------------------------------------------------------------------------
// Every concrete claim the public website makes, mapped to the file + code block
// that substantiates it, with a status: substantiated / partial / unbacked. The
// source of truth is docs/business-claims-audit.json (generated by the claims
// audit; editable by hand). The superadmin reads it in the console behind the
// same authenticator step-up as the AI config, and can download a signed report
// (SHA-256 + HMAC authenticity seal, per the standing report-signing rule).
// ---------------------------------------------------------------------------
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { attestReport, attestationText, REPORT_CONTACTS } from './report_sign.js'

const __dir = path.dirname(fileURLToPath(import.meta.url))
const CLAIMS_PATH = path.join(__dir, '..', 'docs', 'business-claims-audit.json')

export function loadClaims() {
  try {
    const arr = JSON.parse(fs.readFileSync(CLAIMS_PATH, 'utf8'))
    return Array.isArray(arr) ? arr : []
  } catch { return [] }
}
export function claimsSummary() {
  const arr = loadClaims()
  const by = { substantiated: 0, partial: 0, unbacked: 0 }
  for (const c of arr) if (by[c.status] != null) by[c.status]++
  return { total: arr.length, ...by }
}
// The full payload the console renders: claims + counts + an authenticity seal.
export function claimsReport() {
  const claims = loadClaims()
  const summary = claimsSummary()
  const att = attestReport({ claims, summary }, { reportId: 'business-claims', kind: 'claims-traceability' })
  return { claims, summary, attestation: att, contacts: REPORT_CONTACTS, generatedAt: att.issuedAt }
}
// A human-readable Markdown export, with the authenticity block appended.
export function claimsMarkdown() {
  const { claims, summary, attestation, contacts } = claimsReport()
  const L = []
  L.push('# WorkCoPilot - Business Claims Traceability')
  L.push('')
  L.push(`Generated ${attestation.issuedAt}. Each public claim mapped to the file and code block that backs it.`)
  L.push('')
  L.push(`**Summary:** ${summary.total} claims - ${summary.substantiated} substantiated, ${summary.partial} partial, ${summary.unbacked} unbacked.`)
  L.push('')
  const order = { unbacked: 0, partial: 1, substantiated: 2 }
  const sorted = claims.slice().sort((a, b) => (order[a.status] ?? 9) - (order[b.status] ?? 9))
  for (const c of sorted) {
    L.push(`## [${String(c.status || '').toUpperCase()}] ${c.claim}`)
    L.push('')
    if (c.page) L.push(`- **Stated on:** ${c.page}`)
    if (c.category) L.push(`- **Category:** ${c.category}`)
    if (c.risk) L.push(`- **Honesty risk:** ${c.risk}`)
    if (Array.isArray(c.evidence) && c.evidence.length) {
      L.push('- **Backed by:**')
      for (const e of c.evidence) L.push(`    - \`${e.file}${e.line ? ':' + e.line : ''}\`${e.symbol ? ` (${e.symbol})` : ''} - ${e.note || ''}`)
    } else {
      L.push('- **Backed by:** _no code evidence found_')
    }
    L.push('')
  }
  L.push('---')
  L.push('')
  L.push('## Authenticity')
  L.push('')
  for (const line of attestationText(attestation).split('\n')) L.push(line)
  L.push('')
  L.push(`Questions about these claims: ${contacts.join(' , ')}`)
  L.push('')
  return L.join('\n')
}
